CommonData.BannerCustomCSS:
.onetrust-pc-dark-filter {
  background: rgba(0,0,0,0.25) !important;
}

#onetrust-banner-sdk.otCenterRounded {
  max-width: 748px !important;
  border-radius: 12px !important;
  border-bottom: 4px solid #EEB717 !important;
  box-shadow: 0px 2px 2px rgba(0,0,0,0.3) !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  min-height: 440px !important;
  max-height: 90% !important;
}

#onetrust-banner-sdk .ot-sdk-container {
  font-family: "Jumbo The Sans", JumboTheSans, sans-serif !important;
  max-width: 748px !important;
  margin: 0 !important;
  font-size: 16px !important;
  line-height: 22px !important;
}

#onetrust-banner-sdk button {
  letter-spacing: initial !important;
}

@media (max-width: 768px) {
  #onetrust-banner-sdk .ot-sdk-container {
    width: 100% !important;
  }
}

#onetrust-banner-sdk #onetrust-policy {
  margin-top: 32px;
  max-height: 330px !important;
  overflow-y: auto !important;
}

#onetrust-banner-sdk #onetrust-policy-title {
  padding: 0 !important;
  margin: 0 16px 10px !important;
}

#onetrust-banner-sdk .ot-b-addl-desc {
  padding: 0 !important;
  margin: 0 16px 10px !important;
}

#onetrust-banner-sdk .ot-dpd-container {
  padding: 0 !important;
  margin: 0 16px 10px !important;
}

#onetrust-banner-sdk #onetrust-policy-text {
  margin-left: 16px !important;
  margin-right: 16px !important;
}

.ot-sdk-container .ot-dpd-content,
.ot-sdk-container .ot-b-addl-desc,
.ot-sdk-container .ot-dpd-container .ot-dpd-content,
.ot-sdk-container #onetrust-policy-text,
#onetrust-banner-sdk .ot-dpd-desc {
  font-size: 16px !important;
}

.otk-sdk-container .ot-dpd-container {
  margin-top: 16px !important;
}

.ot-sdk-container h3 {
  font-size: 18px !important;
  padding-bottom: 5px !important;
}

#onetrust-banner-sdk #onetrust-button-group-parent {
  background-color: #ffffff !important;
  padding: 16px !important;
  width: 100% !important;
  border-top: 1px solid #e0e0e0 !important;
  box-shadow: none !important;
}

#onetrust-banner-sdk #onetrust-button-group {
  display: block !important;
  line-height: 0 !important;
}

#onetrust-banner-sdk .banner-actions-container {
  display: flex !important;
  float: right !important;
  max-width: initial !important;
  width: initial !important;
}

.banner-actions-container #onetrust-accept-btn-handler {
  border-radius: 24px !important;
  padding: 0px 32px !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  height: 48px !important;
  min-width: auto !important;
  order: 2 !important;
  margin-right: 0 !important;
  margin-bottom: 0 !important;
}

.banner-actions-container #onetrust-accept-btn-handler:hover {
  background-color: #fff !important;
  opacity: 1.0 !important;
}

.banner-actions-container #onetrust-reject-all-handler {
  order: 1 !important;
  min-width: auto !important;
  font-size: 16px !important;
  font-weight: 700 !important;
  margin-bottom: 0 !important;
  margin-right: 16px !important;
  border-radius: 24px !important;
  padding: 0px 32px !important;
  height: 48px !important;
  background-color: #EEB717 !important;
  border-color: #EEB717 !important;
  color: #000000 !important;
}

.banner-actions-container #onetrust-reject-all-handler:hover {
  background-color: #fff !important;
  opacity: 1.0 !important;
}

#onetrust-banner-sdk #onetrust-pc-btn-handler {
  float: left !important;
  border: 1px solid #c8c8c8 !important;
  border-radius: 24px !important;
  height: 48px !important;
  padding: 0 25px !important;
  font-size: 16px !important;
  white-space: nowrap !important;
  text-align: center !important;
  text-decoration: none !important;
  max-width: initial !important;
  margin-bottom: 0 !important;
}

#onetrust-banner-sdk #onetrust-pc-btn-handler:hover {
  background: #000 !important;
  color: #fff !important;
  opacity: 1.0 !important;
  border-color: #000 !important;
}

@media (max-width: 550px) {
  #onetrust-banner-sdk.otCenterRounded {
    top: auto !important;
    bottom: 16px !important;
    left: 16px !important;
    right: 16px !important;
    max-width: calc(100% - 32px) !important;
    transform: none !important;
  }

  #onetrust-banner-sdk #onetrust-button-group {
    display: flex !important;
    flex-direction: column !important;
  }

  #onetrust-banner-sdk .banner-actions-container {
    order: 1 !important;
    width: 100% !important;
    display: flex !important;
    flex-direction: column-reverse !important;
    float: none !important;
    max-width: initial !important;
  }

  #onetrust-banner-sdk #onetrust-pc-btn-handler {
    order: 2 !important;
    float: none !important;
    display: block !important;
    width: 100% !important;
  }

  .banner-actions-container #onetrust-accept-btn-handler {
    width: 100% !important;
    display: block !important;
    max-width: 100% !important;
    margin-bottom: 16px !important;
  }

  .banner-actions-container #onetrust-reject-all-handler {
    width: 100% !important;
    max-width: 100% !important;
    display: block !important;
    margin-bottom: 16px !important;
    margin-right: 0 !important;
  }
}

@media (max-width: 30em) {
  .banner-actions-container {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
  }

  .banner-actions-container #onetrust-reject-all-handler {
    order: 2;
  }

  .banner-actions-container #onetrust-accept-btn-handler {
    order: 1;
  }

  #onetrust-button-group {
    direction: rtl;
  }
}

.ot-floating-button {
  position: relative !important;
}

#ot-sdk-btn-floating .ot-floating-button__front {
  background-color: #757575 !important;
}

#ot-sdk-btn-floating .ot-floating-button__back {
  background-color: #757575 !important;
}

CommonData.PCCustomCSS:
#onetrust-consent-sdk #onetrust-pc-sdk {
    max-width: 748px !important;
    border-radius: 12px !important;
    border-bottom: 4px solid #EEB717 !important;
    top: 5% !important;
    max-height: 90% !important;
    transform: none !important;
    width: auto !important;
    font-family: "Jumbo The Sans", JumboTheSans, sans-serif !important;
    font-size: 16px !important;
    line-height: 22px !important;
    overflow-y: auto !important;
}

#onetrust-pc-sdk #ot-pc-lst {
    position: static !important;
}

#onetrust-pc-sdk .ot-chkbox input:checked~label::before {
    background-color: #EEB717 !important;
}

#onetrust-pc-sdk .ot-chkbox label::before {
    border: 1px solid #EEB717 !important;
}

#onetrust-pc-sdk button {
    letter-spacing: initial !important;
}

#onetrust-pc-sdk div[role=alertdialog] {
    overflow-y: auto !important;
}

@media (max-width: 768px) {
    #onetrust-consent-sdk #onetrust-pc-sdk {
        width: 95% !important;
        min-width: auto !important;
        overflow-y: auto !important;
    }
}

#onetrust-consent-sdk #onetrust-pc-sdk p {
    font-family: "Jumbo The Sans", JumboTheSans, sans-serif !important;
    font-size: 16px !important;
    line-height: 22px !important;
}

#onetrust-consent-sdk #onetrust-pc-sdk h3 {
    font-size: 18px !important;
    padding-bottom: 5px !important;
}


#onetrust-consent-sdk #onetrust-pc-sdk h4 {
    font-size: 18px !important;
}

#onetrust-pc-sdk .ot-plus-minus {
    top: 5px !important;
}

#onetrust-pc-sdk .ot-accordion-layout h4~.ot-always-active {
    color: #9e9e9e !important;
}

#onetrust-pc-sdk #ot-pc-content {
    position: static !important;
    top: initial !important;
    bottom: initial !important;
    padding-bottom: 30px !important;
}

#onetrust-pc-sdk .ot-pc-footer {
    position: relative !important;
    bottom: 0px;
    width: 100%;
    max-height: 160px;
    border-top: 1px solid #d8d8d8;
}

#onetrust-pc-sdk.otPcCenter {
    bottom: initial !important;
}

#onetrust-pc-sdk .ot-accordion-layout .ot-acc-grpcntr {
    position: relative !important;
}

#onetrust-pc-sdk .ot-btn-container {
    background-color: #fff !important;
    position: relative !important;
    z-index: 2 !important;
}

.ot-pc-footer-logo {
    display: none !important;
}

#onetrust-pc-sdk #accept-recommended-btn-handler, #onetrust-pc-sdk .ot-btn-container .save-preference-btn-handler {
    border-radius: 22px !important;
    padding: 0px 32px !important;
    font-size: 16px !important;
    font-weight: 700 !important;
    height: 44px !important;
    min-width: auto !important;
    order: 1 !important;
    margin-bottom: 32px !important;
}

#onetrust-pc-sdk #accept-recommended-btn-handler:hover, #onetrust-pc-sdk .ot-btn-container .save-preference-btn-handler:hover {
    background: #fff !important;
    opacity: 1.0 !important;
}

@media (max-width: 768px) {
    #onetrust-pc-sdk .ot-btn-container {
        display: block !important;
    }

    #onetrust-pc-sdk #accept-recommended-btn-handler {
        display: block !important;
        width: 100% !important;
        max-width: initial !important;
    }
}

#onetrust-pc-sdk .ot-btn-container .save-preference-btn-handler {
    margin-top: 12px !important;
    margin-bottom: 12px !important;
    width: auto !important;
    margin-right: 0 !important;
}

#onetrust-pc-sdk .ot-btn-container .ot-pc-refuse-all-handler {
    width: auto !important;
    order: 2 !important;
    min-width: auto !important;
    font-size: 16px !important;
    font-weight: 700 !important;
    margin-bottom: 0 !important;
    max-width: calc(50% - 18px);
    border: none !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    color: #000000 !important;
    background-color: #ffffff !important;
    text-decoration: none !important;
}

#onetrust-pc-sdk .ot-btn-container .ot-pc-refuse-all-handler:hover {
    opacity: 1.0 !important;
    text-decoration: underline !important;
}

#onetrust-pc-sdk .ot-accordion-layout.ot-cat-item:first-of-type {
    border-top-right-radius: 12px;
    border-top-left-radius: 12px;
}

#onetrust-pc-sdk .ot-switch-nob {
    border: 1px solid #9E9E9E !important;
    background-color: #9E9E9E;
}

#onetrust-pc-sdk .ot-tgl input:checked+.ot-switch .ot-switch-nob {
    border: 1px solid #EEB717 !important;
    background-color: #EEB717;
}

#onetrust-pc-sdk .ot-tgl input:checked+.ot-switch .ot-switch-nob:before, #onetrust-pc-sdk .ot-switch-nob:before {
    border-color: #fff !important;
    background-color: #fff;
}

#onetrust-pc-sdk .ot-accordion-layout.ot-cat-item:last-of-type {
    border-bottom-right-radius: 12px;
    border-bottom-left-radius: 12px;
}

#onetrust-pc-sdk .ot-accordion-layout .ot-acc-grpdesc,
#onetrust-consent-sdk #onetrust-pc-sdk #ot-pc-desc {
    font-size: 16px !important;
}

.cookie-setting-button {
    background-color: #fff !important;
    border-color: #c8c8c8 !important;
    font-size: 1em !important;
    color: #000 !important;
    border-radius: 30px;
    font-size: 1em !important;
    color: #000 !important;
    font-family: JumboTheSans, Jumbo The Sans, "sans-serif";
    font-weight: 700;
    display: inline-flex;
    transition-duration: .2s !important;
    transition-property: background-color, border, color !important;
    transition-timing-function: ease-in-out !important;
    vertical-align: middle;
    margin: 0em;
}

.cookie-setting-button:hover {
    background-color: #000 !important;
    color: #fff !important;
}

.ot-pc-refuse-all-handler {
    border: none !important;
    text-decoration: underline !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    color: #000000 !important;
    background-color: #FFFFFF !important;
}

@media (max-width: 30em) {
    .ot-btn-container {
        display: -webkit-box;
        display: -moz-box;
        display: -ms-flexbox;
        display: -webkit-flex;
        display: flex;
        -webkit-box-orient: vertical;
        -moz-box-orient: vertical;
        -webkit-flex-direction: column;
        -ms-flex-direction: column;
        flex-direction: column;
        /* optional */
        -webkit-box-align: start;
        -moz-box-align: start;
        -ms-flex-align: start;
        -webkit-align-items: flex-start;
        align-items: flex-start;
    }

    .ot-btn-container .ot-pc-refuse-all-handler {
        -webkit-box-ordinal-group: 2;
        -moz-box-ordinal-group: 2;
        -ms-flex-order: 2;
        -webkit-order: 2;
        order: 2;
    }

    .ot-btn-container .save-preference-btn-handler {
        -webkit-box-ordinal-group: 1;
        -moz-box-ordinal-group: 1;
        -ms-flex-order: 1;
        -webkit-order: 1;
        order: 1;
    }
}
